	{
		double rl, img;

		inline complex() : rl(0), img(0) {}

		inline complex(double _rl, double _img)
			: rl(_rl), img(_img) {}

		inline friend complex operator+(complex a, complex b)
		{
			return complex(a.rl + b.rl, a.img + b.img);
		}

		inline friend complex operator-(complex a, complex b)
		{
			return complex(a.rl - b.rl, a.img - b.img);
		}

		inline friend complex operator*(complex a, complex b)
		{
			return complex(
				a.rl * b.rl - a.img * b.img,
				a.rl * b.img + b.rl * a.img
			);
		}
	} A[N << 2], B[N << 2];

