			{
				complex omega(1, 0);
				for (int k = j; k < j + i / 2; ++k)
				{
					complex u = a[k];
					complex t = a[k + i / 2] * omega;
					a[k] = u + t;
					a[k + i / 2] = u - t;
					omega = omega * omega_i;
				}
			}
		}

		if (opt == -1)
			for (int i = 0; i < len; ++i)
				a[i].rl /= len;
	}

