		for (int j = 0; j <= n; ++j)
			f[j][i] = (res[j] + _f[j][i] +
				_f[j][i ^ ((b >> 1) & 1)]) % q;
	}

	if (b & 1)
	{
		std::swap(f, _f);

		for (int i = 0; i < 2; ++i)
		{
			f[0][i] = _f[0][i];

			for (int j = 1; j <= n; ++j)
